
USE [olist_dwh];
GO

--=========================================================================
-- create the order status dimension table
-- i am creating the order status dimension in the gold schema.
-- order_status_key will be the surrogate key generated by sql server.
-- order_status will identify each distinct order status.
--=========================================================================

IF OBJECT_ID('[gold].[dim_order_status]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_order_status]
    (
        order_status_key INT IDENTITY(1,1) NOT NULL,
        order_status VARCHAR(50) NOT NULL,

        CONSTRAINT PK_dim_order_status
            PRIMARY KEY (order_status_key)
    );
END;
GO

--=========================================================================
-- create a unique index for the order status business key
-- i am ensuring that each order status can only appear once
-- in the dimension.
-- this prevents duplicate status records from being inserted.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_order_status'
      AND object_id = OBJECT_ID('[gold].[dim_order_status]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_order_status
    ON [gold].[dim_order_status] (order_status);
END;
GO

--=========================================================================
-- insert the unknown order status record
-- i am inserting an unknown status with order_status_key = -1.
-- this record will be used when an order status cannot be matched
-- to a record in the order status dimension.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM [gold].[dim_order_status]
    WHERE order_status_key = -1
)
BEGIN
    SET IDENTITY_INSERT [gold].[dim_order_status] ON;

    INSERT INTO [gold].[dim_order_status]
    (
        order_status_key,
        order_status
    )
    VALUES
    (
        -1,
        'Unknown'
    );

    SET IDENTITY_INSERT [gold].[dim_order_status] OFF;
END;
GO
